const void *purr_icon_get(const char *name)
{
    if (!name) return NULL;    // callers pass icon_name_for_app()'s NULL straight through
    for (size_t i = 0; i < sizeof(s_icons) / sizeof(s_icons[0]); i++) {
        if (strcmp(s_icons[i].name, name) == 0) return s_icons[i].dsc;
    }
    return NULL;
}

